"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { db, type DailyCheckin, type FoodFavorite, type Goal, type Meal, type Workout, type WorkoutExercise, type WorkoutProgram, type WeightEntry, type HuaweiSync } from "../lib/db";
import { type Lang, t } from "../lib/i18n";
import { calculateTargets, dailyRecommendation, weightTrend, type ActivityLevel, type GoalMode, type Sex, type Profile } from "../lib/health";

const todayKey=()=>new Date().toISOString().slice(0,10);
const mealTypes=["Breakfast","Lunch","Dinner","Snack"] as const;
const DEFAULT_GOAL:Goal={calories:2300,protein:150,carbs:250,fat:75,targetWeight:75,updatedAt:Date.now()};
const STAPLES=[
  {name:"Chicken breast, grilled",calories100g:165,protein100g:31,carbs100g:0,fat100g:3.6,source:"Health OS"},
  {name:"White rice, cooked",calories100g:130,protein100g:2.7,carbs100g:28.2,fat100g:.3,source:"Health OS"},
  {name:"Egg, whole",calories100g:143,protein100g:12.6,carbs100g:.7,fat100g:9.5,source:"Health OS"},
  {name:"Greek yogurt",calories100g:97,protein100g:9,carbs100g:3.9,fat100g:5,source:"Health OS"},
  {name:"Oats",calories100g:389,protein100g:16.9,carbs100g:66.3,fat100g:6.9,source:"Health OS"},
  {name:"Banana",calories100g:89,protein100g:1.1,carbs100g:22.8,fat100g:.3,source:"Health OS"},
];

export default function HealthApp(){
  const [lang,setLang]=useState<Lang>("en");
  const [tab,setTab]=useState<"home"|"nutrition"|"workout"|"progress">("home");
  const [meals,setMeals]=useState<Meal[]>([]),[workouts,setWorkouts]=useState<Workout[]>([]),[weights,setWeights]=useState<WeightEntry[]>([]),[goal,setGoal]=useState<Goal>(DEFAULT_GOAL),[checkin,setCheckin]=useState<DailyCheckin|null>(null),[profile,setProfile]=useState<Profile|null>(null),[programs,setPrograms]=useState<WorkoutProgram[]>([]),[huaweiSync,setHuaweiSync]=useState<HuaweiSync|null>(null);
  const [scanner,setScanner]=useState(false),[foodLookup,setFoodLookup]=useState(false),[workoutEditor,setWorkoutEditor]=useState(false),[weightEditor,setWeightEditor]=useState(false),[goalEditor,setGoalEditor]=useState(false),[profileEditor,setProfileEditor]=useState(false),[programEditor,setProgramEditor]=useState(false),[settings,setSettings]=useState(false),[loading,setLoading]=useState(true);
  const [plan,setPlan]=useState<any[]>([]);
  useEffect(()=>{const saved=localStorage.getItem("health-os-language") as Lang|null;if(saved==="ar"||saved==="en")setLang(saved)},[]);
  useEffect(()=>{if("serviceWorker" in navigator)navigator.serviceWorker.register("/sw.js").catch(()=>{})},[]);
  const changeLang=(next:Lang)=>{setLang(next);localStorage.setItem("health-os-language",next)};
  async function refresh(){const [m,w,wt,g,c,p,pg,hs]=await Promise.all([db.meals.orderBy("createdAt").reverse().toArray(),db.workouts.orderBy("date").reverse().toArray(),db.weights.orderBy("date").reverse().toArray(),db.goals.orderBy("updatedAt").reverse().first(),db.checkins.where("date").equals(todayKey()).first(),db.profiles.orderBy("updatedAt").reverse().first(),db.programs.orderBy("updatedAt").reverse().toArray(),db.huaweiSyncs.orderBy("syncedAt").reverse().first()]);setMeals(m);setWorkouts(w);setWeights(wt);setGoal(g||DEFAULT_GOAL);setCheckin(c||null);setProfile(p||null);setPrograms(pg);setHuaweiSync(hs||null)}
  useEffect(()=>{refresh().finally(()=>setLoading(false))},[]);
  const todayMeals=useMemo(()=>meals.filter(m=>new Date(m.createdAt).toISOString().slice(0,10)===todayKey()),[meals]);
  const totals=useMemo(()=>todayMeals.reduce((a,m)=>({calories:a.calories+Number(m.calories||0),protein:a.protein+Number(m.protein||0),carbs:a.carbs+Number(m.carbs||0),fat:a.fat+Number(m.fat||0)}),{calories:0,protein:0,carbs:0,fat:0}),[todayMeals]);
  const targets=profile?{...calculateTargets(profile),targetWeight:profile.targetWeight}:goal;
  const todayWorkout=workouts.find(w=>w.date===todayKey()&&!w.completed);
  const todayWorkoutAny=workouts.find(w=>w.date===todayKey());
  const trend=useMemo(()=>weightTrend(weights),[weights]);
  const insight=useMemo(()=>dailyRecommendation({calories:totals.calories,protein:totals.protein,goalCalories:targets.calories,goalProtein:targets.protein,weightPerWeek:trend.perWeek,goalMode:profile?.goalMode||"maintain"}),[totals,targets,trend,profile]);
  async function addMeal(meal:Omit<Meal,"id"|"createdAt">){await db.meals.add({...meal,createdAt:Date.now()});setScanner(false);setFoodLookup(false);await refresh()}
  async function saveWorkout(workout:Omit<Workout,"id"|"createdAt">){await db.workouts.add({...workout,createdAt:Date.now()});setWorkoutEditor(false);await refresh()}
  async function saveWeight(weight:number,note:string){await db.weights.add({weight,note,date:todayKey(),createdAt:Date.now()});setWeightEditor(false);await refresh()}
  async function saveGoal(next:Goal){await db.goals.add({...next,updatedAt:Date.now()});setGoalEditor(false);await refresh()}
  async function saveCheckin(next:Omit<DailyCheckin,"id"|"createdAt">){if(checkin?.id)await db.checkins.update(checkin.id,next);else await db.checkins.add({...next,createdAt:Date.now()});await refresh()}
  async function saveProfile(next:Profile){const existing=profile?.id;if(existing)await db.profiles.update(existing,{...next,updatedAt:Date.now()});else await db.profiles.add({...next,updatedAt:Date.now()});const g=calculateTargets(next);await saveGoal({...g,targetWeight:next.targetWeight,updatedAt:Date.now()});setProfileEditor(false);await refresh()}
  async function saveProgram(p:WorkoutProgram){await db.programs.add({...p,updatedAt:Date.now()});setProgramEditor(false);await refresh()}
  async function applyProgram(p:WorkoutProgram,dayIndex=0){const d=p.days[dayIndex]||p.days[0];if(!d)return;await saveWorkout({name:`${p.name} · ${d.name}`,date:todayKey(),duration:60,calories:300,notes:"",exercises:d.exercises.map(x=>({...x})),completed:false,programId:p.id})}
  async function exportBackup(){const data={version:6,exportedAt:new Date().toISOString(),meals:await db.meals.toArray(),workouts:await db.workouts.toArray(),weights:await db.weights.toArray(),goals:await db.goals.toArray(),checkins:await db.checkins.toArray(),favorites:await db.favorites.toArray(),profiles:await db.profiles.toArray(),programs:await db.programs.toArray(),huaweiSyncs:await db.huaweiSyncs.toArray()};downloadFile("health-os-backup.json",JSON.stringify(data,null,2),"application/json")}
  async function exportCsv(){const rows=["date,type,name,calories,protein,carbs,fat",""].join("\n")+meals.map(m=>`${new Date(m.createdAt).toISOString().slice(0,10)},meal,"${m.name.replace(/"/g,'""')}",${m.calories},${m.protein},${m.carbs},${m.fat}`).join("\n");downloadFile("health-os-meals.csv",rows,"text/csv;charset=utf-8")}
  async function importBackup(file:File){try{const raw=JSON.parse(await file.text());if(!raw||raw.version<1)throw new Error();for(const table of ["meals","workouts","weights","goals","checkins","favorites","profiles","programs","huaweiSyncs"] as const){if(Array.isArray(raw[table])&&raw[table].length)await (db as any)[table].bulkPut(raw[table])}alert(t(lang,"importDone"));location.reload()}catch{alert(t(lang,"invalidBackup"))}}
  async function importHuawei(file:File){try{const text=await file.text();let records:any[]=[];if(file.name.toLowerCase().endsWith(".json")){const raw=JSON.parse(text);records=Array.isArray(raw)?raw:(raw.records||raw.data||raw.items||[])}else{records=parseHuaweiCsv(text)};if(!records.length)throw new Error("empty");let imported=0;const byDate=new Map<string,{steps:number;sleep:number;water:number}>();for(const r of records){const date=String(r.date||r.startDate||r.start||r.day||"").slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;const type=String(r.type||r.metric||r.name||"").toLowerCase();const value=Number(r.value??r.amount??r.steps??r.hours??0);if(!Number.isFinite(value))continue;const item=byDate.get(date)||{steps:0,sleep:0,water:0};if(type.includes("step"))item.steps+=Math.max(0,value);else if(type.includes("sleep")){item.sleep+=value>24?value/60:value}else if(type.includes("water")){item.water+=value>20?value/250:value}byDate.set(date,item);imported++}for(const [date,v] of byDate){const existing=await db.checkins.where("date").equals(date).first();const next={date,steps:Math.round(v.steps),sleep:Number(v.sleep.toFixed(1)),water:Number(v.water.toFixed(1)),mood:existing?.mood||3,createdAt:existing?.createdAt||Date.now()};if(existing?.id)await db.checkins.update(existing.id,next);else await db.checkins.add(next)}await db.huaweiSyncs.add({source:"huawei-health",syncedAt:Date.now(),importedAt:Date.now(),records:imported,note:file.name});await refresh();alert(t(lang,"huaweiImportDone"))}catch{alert(t(lang,"huaweiImportError"))}}
  if(loading)return <div className="loadingScreen"><div className="loadingMark">✦</div><strong>{t(lang,"loading")}</strong></div>;
  const title=tab==="home"?t(lang,"goodMorning"):t(lang,tab);
  return <main className={`app lang-${lang}`} dir={lang==="ar"?"rtl":"ltr"}><div className="ambient ambientOne"/><div className="ambient ambientTwo"/><div className="shell">
    <header className="topbar"><div className="brandBlock"><div className="brandIcon">✦</div><div><div className="eyebrow">{t(lang,"appName")}</div><h1 className="title">{title} {tab==="home"&&"👋"}</h1></div></div><button className="avatar" onClick={()=>setSettings(true)}>A</button></header>
    {!profile&&<ProfilePrompt lang={lang} onOpen={()=>setProfileEditor(true)}/>} 
    {tab==="home"&&<Home lang={lang} totals={totals} goal={targets} todayMeals={todayMeals} todayWorkout={todayWorkout} todayWorkoutAny={todayWorkoutAny} weights={weights} checkin={checkin} profile={profile} insight={insight} onScan={()=>setScanner(true)} onWorkout={()=>setWorkoutEditor(true)} onWeight={()=>setWeightEditor(true)} onGoal={()=>setGoalEditor(true)} onCheckin={saveCheckin} onNutrition={()=>setTab("nutrition")} onFoodLookup={()=>setFoodLookup(true)} onProgress={()=>setTab("progress")} onProfile={()=>setProfileEditor(true)} />}
    {tab==="nutrition"&&<Nutrition lang={lang} meals={todayMeals} totals={totals} goal={targets} onScan={()=>setScanner(true)} onLookup={()=>setFoodLookup(true)} onDelete={async (id?: number)=>{if(id){await db.meals.delete(id);await refresh()}}} onPlan={plan} onSetPlan={setPlan}/>} 
    {tab==="workout"&&<WorkoutPage lang={lang} workouts={workouts} programs={programs} onAdd={()=>setWorkoutEditor(true)} onProgram={()=>setProgramEditor(true)} onApply={applyProgram} onRefresh={refresh}/>} 
    {tab==="progress"&&<Progress lang={lang} weights={weights} goal={targets} profile={profile} workouts={workouts} meals={meals} checkins={checkin} onWeight={()=>setWeightEditor(true)} />}
    </div><nav className="bottomNav">{([['home','⌂'],['nutrition','◉'],['workout','▣'],['progress','↗']] as const).map(([id,icon])=><button key={id} className={`navItem ${tab===id?'active':''}`} onClick={()=>setTab(id)}><span className="navIcon">{icon}</span><span>{t(lang,id)}</span></button>)}</nav>
    {scanner&&<FoodScanner lang={lang} onClose={()=>setScanner(false)} onAdd={addMeal}/>} {foodLookup&&<FoodLookup lang={lang} onClose={()=>setFoodLookup(false)} onAdd={addMeal}/>} {workoutEditor&&<WorkoutEditor lang={lang} onClose={()=>setWorkoutEditor(false)} onSave={saveWorkout}/>} {weightEditor&&<WeightEditor lang={lang} onClose={()=>setWeightEditor(false)} onSave={saveWeight}/>} {goalEditor&&<GoalEditor lang={lang} goal={targets} onClose={()=>setGoalEditor(false)} onSave={saveGoal}/>} {profileEditor&&<ProfileEditor lang={lang} profile={profile} onClose={()=>setProfileEditor(false)} onSave={saveProfile}/>} {programEditor&&<ProgramEditor lang={lang} onClose={()=>setProgramEditor(false)} onSave={saveProgram}/>} {settings&&<Settings lang={lang} onLang={changeLang} onClose={()=>setSettings(false)} onClear={async()=>{if(confirm(t(lang,"danger"))){await Promise.all([db.meals.clear(),db.workouts.clear(),db.weights.clear(),db.goals.clear(),db.checkins.clear(),db.favorites.clear(),db.profiles.clear(),db.programs.clear(),db.huaweiSyncs.clear()]);location.reload()}}} onExport={exportBackup} onImport={importBackup} onCsv={exportCsv} onHuaweiImport={importHuawei} huaweiSync={huaweiSync}/>} 
  </main>;
}

function ProfilePrompt({lang,onOpen}:any){return <section className="card setupCard"><div className="setupIcon">◎</div><div><h2>{t(lang,"setup")}</h2><p>{t(lang,"setupHint")}</p></div><button className="primaryButton" onClick={onOpen}>{t(lang,"setup")}</button></section>}
function Home({lang,totals,goal,todayMeals,todayWorkout,todayWorkoutAny,weights,checkin,profile,insight,onScan,onWorkout,onWeight,onGoal,onCheckin,onNutrition,onFoodLookup,onProgress,onProfile}:any){const pct=Math.min(100,goal.calories?totals.calories/goal.calories*100:0);const latest=weights[0]?.weight;const score=Math.round(Math.min(100,(totals.calories<=goal.calories?55:35)+(Math.min(1,totals.protein/Math.max(goal.protein,1))*25)+(todayWorkoutAny?.completed?15:todayWorkoutAny?5:0)+(Math.min(1,(checkin?.water||0)/8)*5)));return <>
  <section className="card heroCard"><div className="heroTop"><div><span className="muted">{t(lang,"caloriesToday")}</span><div className="heroKcal">{Math.round(totals.calories)} <small>{t(lang,"kcal")}</small></div></div><button className="pillButton" onClick={onGoal}>{t(lang,"goals")}</button></div><div className="progressTrack"><span style={{width:`${pct}%`}}/></div><div className="goalLine"><span>{Math.max(0,Math.round(goal.calories-totals.calories))} {t(lang,"kcal")} {t(lang,"remaining")}</span><span>{goal.calories} {t(lang,"goal")}</span></div><div className="macroGrid"><Macro lang={lang} value={totals.protein} goal={goal.protein} label="protein"/><Macro lang={lang} value={totals.carbs} goal={goal.carbs} label="carbs"/><Macro lang={lang} value={totals.fat} goal={goal.fat} label="fat"/></div></section>
  <div className="scoreRow"><div className="scoreRing"><strong>{score}</strong><span>{t(lang,"healthScore")}</span></div><div className="insightBox"><span className="eyebrow">{t(lang,"smartInsight")}</span><strong>{insight[0]}</strong><button className="textButton" onClick={onProgress}>{t(lang,"weeklyReport")} →</button></div></div>
  <div className="quickGrid"><Quick icon="⌁" title={t(lang,"scanFood")} sub={t(lang,"scanFoodSub")} onClick={onScan} primary/><Quick icon="⌕" title={t(lang,"findFood")} sub={t(lang,"findFoodSub")} onClick={onFoodLookup}/><Quick icon="▣" title={t(lang,"logWorkout")} sub={todayWorkout?t(lang,"planned"):t(lang,"createFirst")} onClick={onWorkout}/><Quick icon="◉" title={t(lang,"weight")} sub={latest?`${latest} kg`:t(lang,"addWeight")} onClick={onWeight}/></div>
  <SectionTitle lang={lang} title={t(lang,"recommendations")}/><section className="card insightList">{insight.slice(0,3).map((x:string,i:number)=><div className="recommendRow" key={i}><span>✦</span><p>{x}</p></div>)}</section>
  <SectionTitle lang={lang} title={t(lang,"todaysPlan")} meta={`${todayMeals.length} ${t(lang,"meals")}`}/><section className="card listCard"><PlanRow icon="◉" label={t(lang,"nutritionLabel")} value={`${Math.round(totals.calories)} / ${goal.calories} ${t(lang,"kcal")}`}/><PlanRow icon="▣" label={t(lang,"workoutLabel")} value={todayWorkout?.name||t(lang,"noWorkout")}/><PlanRow icon="○" label={t(lang,"water")} value={`${checkin?.water||0} / 8 ${t(lang,"glasses")}`}/><PlanRow icon="↗" label={t(lang,"steps")} value={`${checkin?.steps||0}`}/></section>
  <SectionTitle lang={lang} title={t(lang,"dailyCheckin")}/><CheckinCard lang={lang} checkin={checkin} onSave={onCheckin}/><SectionTitle lang={lang} title={t(lang,"recentMeals")} action={t(lang,"seeAll")} onAction={onNutrition}/><div className="meals">{todayMeals.slice(0,4).map((m:Meal)=><MealRow lang={lang} key={m.id} meal={m}/>)}{!todayMeals.length&&<Empty icon="◉" title={t(lang,"noMeals")} text={t(lang,"firstMeal")}/>}</div><button className="ghostWide" onClick={onProfile}>◎ {profile?t(lang,"editProfile"):t(lang,"setup")}</button></>}
function Quick({icon,title,sub,onClick,primary}:any){return <button className={`quickCard ${primary?'primary':''}`} onClick={onClick}><span className="quickIcon">{icon}</span><strong>{title}</strong><small>{sub}</small></button>}
function PlanRow({icon,label,value}:any){return <div className="planRow"><span><i>{icon}</i>{label}</span><strong>{value}</strong></div>}
function SectionTitle({title,meta,action,onAction,lang}:any){return <div className="sectionTitle"><h2>{title}</h2>{action?<button className="textButton" onClick={onAction}>{action}</button>:<span className="muted">{meta}</span>}</div>}
function Macro({value,goal,label,lang}:any){return <div className="macro"><strong>{Math.round(value)}<small>g</small></strong><span>{t(lang,label)} · {goal}g</span><div className="miniTrack"><span style={{width:`${Math.min(100,goal?value/goal*100:0)}%`}}/></div></div>}
function MealRow({meal,lang}:any){return <div className="mealRow"><div className="mealDot">◉</div><div className="mealMain"><strong>{meal.name}</strong><span>{Math.round(meal.protein)}g {t(lang,"protein")} · {Math.round(meal.carbs)}g {t(lang,"carbs")} · {t(lang,(meal.mealType||"Snack").toLowerCase() as any)}</span></div><b>{Math.round(meal.calories)}</b></div>}
function Empty({icon,title,text}:any){return <div className="emptyCard"><div className="emptyIcon">{icon}</div><strong>{title}</strong><span>{text}</span></div>}

function Nutrition({lang,meals,totals,goal,onScan,onLookup,onDelete,onPlan,onSetPlan}:any){const [showPlanner,setShowPlanner]=useState(false);return <><section className="card intakeCard"><div className="muted">{t(lang,"todayIntake")}</div><div className="bigNumber">{Math.round(totals.calories)} <small>/ {goal.calories} {t(lang,"kcal")}</small></div><div className="macroGrid"><Macro lang={lang} value={totals.protein} goal={goal.protein} label="protein"/><Macro lang={lang} value={totals.carbs} goal={goal.carbs} label="carbs"/><Macro lang={lang} value={totals.fat} goal={goal.fat} label="fat"/></div></section><div className="nutritionActions"><button className="primaryButton" onClick={onScan}>⌁ {t(lang,"scanWithAI")}</button><button className="secondaryButton" onClick={onLookup}>⌕ {t(lang,"searchBarcode")}</button><button className="secondaryButton" onClick={()=>setShowPlanner(v=>!v)}>✦ {t(lang,"mealPlanner")}</button></div>{showPlanner&&<MealPlanner lang={lang} goal={goal} meals={meals} plan={onPlan} onSetPlan={onSetPlan} />}{mealTypes.map(g=>{const list=meals.filter((m:Meal)=>(m.mealType||"Snack")===g);if(!list.length)return null;return <section key={g}><SectionTitle lang={lang} title={t(lang,g.toLowerCase() as any)}/><div className="meals">{list.map((m:Meal)=><div className="mealRowWrap" key={m.id}><MealRow lang={lang} meal={m}/><button className="rowDelete" onClick={()=>onDelete(m.id)}>×</button></div>)}</div></section>})}{!meals.length&&<Empty icon="◉" title={t(lang,"nothingLogged")} text={t(lang,"reviewBeforeSaving")}/>}</>}
function MealPlanner({lang,goal,meals,plan,onSetPlan}:any){const [items,setItems]=useState<any[]>(plan);const remaining=Math.max(0,goal.calories-meals.reduce((a:any,m:any)=>a+m.calories,0));const remainingP=Math.max(0,goal.protein-meals.reduce((a:any,m:any)=>a+m.protein,0));const build=()=>{let kcal=0,p=0;const chosen=[];for(const f of STAPLES){if(kcal>=remaining*.9&&p>=remainingP*.8)break;const g=f.name.includes("Chicken")?180:f.name.includes("Rice")?180:100;chosen.push({...f,grams:g,calories:f.calories100g*g/100,protein:f.protein100g*g/100});kcal+=f.calories100g*g/100;p+=f.protein100g*g/100}setItems(chosen);onSetPlan(chosen)};return <section className="card plannerCard"><div className="sectionTitle"><h2>{t(lang,"mealPlanner")}</h2><span className="muted">{Math.round(remaining)} kcal · {Math.round(remainingP)}g P</span></div><button className="primaryButton fullButton" onClick={build}>✦ {t(lang,"generatePlan")}</button>{items.length>0&&<><div className="planFoodList">{items.map((x:any,i:number)=><div key={i}><span>{x.name} · {x.grams}g</span><b>{Math.round(x.calories)} kcal</b></div>)}</div><div className="note">{t(lang,"planReady")}</div></>}</section>}

function WorkoutPage({lang,workouts,programs,onAdd,onProgram,onApply,onRefresh}:any){const upcoming=workouts.filter((w:Workout)=>!w.completed).slice(0,8),done=workouts.filter((w:Workout)=>w.completed).slice(0,8);async function complete(id?:number){if(id){await db.workouts.update(id,{completed:true});await onRefresh()}}async function remove(id?:number){if(id){await db.workouts.delete(id);await onRefresh()}}return <><div className="nutritionActions"><button className="primaryButton" onClick={onAdd}>＋ {t(lang,"createWorkout")}</button><button className="secondaryButton" onClick={onProgram}>＋ {t(lang,"createProgram")}</button></div><section className="card statCard"><Stat value={workouts.length} label={t(lang,"sessions")}/><Stat value={workouts.filter((w:Workout)=>w.completed).length} label={t(lang,"completed")}/><Stat value={workouts.reduce((a:number,w:Workout)=>a+w.duration,0)} label={t(lang,"minutes")}/></section><SectionTitle lang={lang} title={t(lang,"programs")}/><div className="programGrid">{programs.map((p:WorkoutProgram)=><div className="card programCard" key={p.id}><div className="programHead"><strong>{p.name}</strong><span>{p.days.length} {t(lang,"day")}</span></div>{p.days.map((d:any,i:number)=><button key={i} className="programDay" onClick={()=>onApply(p,i)}>{d.name}<span>→</span></button>)}</div>)}{!programs.length&&<button className="card presetProgram" onClick={async()=>{for(const p of defaultPrograms())await db.programs.add({...p,updatedAt:Date.now()});await onRefresh()}}>✦ {t(lang,"createProgram")}</button>}</div><SectionTitle lang={lang} title={t(lang,"progression")}/><section className="card insightList">{progressionTips(lang,workouts).map((x:string,i:number)=><div className="recommendRow" key={i}><span>↗</span><p>{x}</p></div>)}</section><SectionTitle lang={lang} title={t(lang,"planned")}/><div className="stack">{upcoming.map((w:Workout)=><WorkoutCard lang={lang} key={w.id} workout={w} onComplete={complete} onDelete={remove}/>)}{!upcoming.length&&<Empty icon="▣" title={t(lang,"noWorkouts")} text={t(lang,"createFirst")}/>}</div>{done.length>0&&<><SectionTitle lang={lang} title={t(lang,"completed")}/><div className="stack">{done.map((w:Workout)=><WorkoutCard lang={lang} key={w.id} workout={w} onDelete={remove}/>)}</div></>}</>}
function Stat({value,label}:any){return <div><strong>{value}</strong><span>{label}</span></div>}
function WorkoutCard({workout,lang,onComplete,onDelete}:any){const best=workout.exercises.reduce((a:any,e:any)=>Math.max(a,e.weight||0),0);return <article className="card workoutCard"><div className="workoutHead"><div><small>{workout.date}</small><h3>{workout.name}</h3></div><span className={`status ${workout.completed?'done':''}`}>{workout.completed?t(lang,"done"):t(lang,"planned")}</span></div><div className="workoutMeta">◷ {workout.duration} min · ⚡ {workout.calories} kcal · {workout.exercises.length} {t(lang,"exercise")} {best>0&&`· ${t(lang,"bestSet")} ${best}kg`}</div>{workout.exercises.length>0&&<div className="exerciseList">{workout.exercises.map((e:any,i:number)=><div className="exerciseRow" key={i}><span>{e.name}</span><strong>{e.sets} × {e.reps}{e.weight?` · ${e.weight}kg`:""}</strong></div>)}</div>}<div className="buttonRow">{!workout.completed&&<button className="smallPrimary" onClick={()=>onComplete(workout.id)}>✓ {t(lang,"complete")}</button>}<button className="smallDanger" onClick={()=>onDelete(workout.id)}>⌫ {t(lang,"delete")}</button></div></article>}

function Progress({lang,weights,goal,profile,workouts,meals,checkins,onWeight}:any){const [range,setRange]=useState(7);const latest=weights[0]?.weight;const first=weights.length?weights[Math.min(weights.length-1,range-1)]:null;const change=latest&&first?latest-first.weight:null;const recentMeals=meals.filter((m:Meal)=>Date.now()-m.createdAt<range*86400000);const recentWorkouts=workouts.filter((w:Workout)=>Date.now()-new Date(w.date).getTime()<range*86400000);const avgCal=recentMeals.length?recentMeals.reduce((a:number,m:Meal)=>a+m.calories,0)/range:0;const avgP=recentMeals.length?recentMeals.reduce((a:number,m:Meal)=>a+m.protein,0)/range:0;const target=profile?.targetWeight??goal.targetWeight;const remaining=latest?latest-target:null;return <><div className="rangeSwitch"><button className={range===7?'selected':''} onClick={()=>setRange(7)}>7 {t(lang,"week")}</button><button className={range===30?'selected':''} onClick={()=>setRange(30)}>30</button></div><section className="card progressCard"><div><span className="muted">{t(lang,"weight")}</span><div className="progressWeight">{latest??"—"}<small>kg</small></div></div><div className="targetBox"><span>{t(lang,"targetWeight")}</span><strong>{target} kg</strong>{change!==null&&<small className={change<=0?'goodText':'badText'}>{change>0?'+':''}{change.toFixed(1)} kg</small>}</div></section><button className="primaryButton fullButton" onClick={onWeight}>＋ {t(lang,"addWeight")}</button><SectionTitle lang={lang} title={t(lang,"weeklyReport")}/><section className="card reportGrid"><ReportStat value={Math.round(avgCal)} label={t(lang,"avgCalories")}/><ReportStat value={`${Math.round(avgP)}g`} label={t(lang,"avgProtein")}/><ReportStat value={recentWorkouts.length} label={t(lang,"workoutsCount")}/><ReportStat value={change===null?'—':`${change>0?'+':''}${change.toFixed(1)}kg`} label={t(lang,"weightChange")}/></section><section className="card"><div className="sectionTitle"><h2>{t(lang,"trend")}</h2><span className="muted">{range===7?t(lang,"last7"):t(lang,"last30")}</span></div><MiniChart values={[...weights].slice(0,range).reverse().map((x:any)=>x.weight)} labels={[...weights].slice(0,range).reverse().map((x:any)=>x.date.slice(5))}/></section><SectionTitle lang={lang} title={t(lang,"weightHistory")}/><div className="stack">{weights.map((w:WeightEntry)=><div className="weightRow card" key={w.id}><div><strong>{w.weight} kg</strong><small>{w.date}</small></div><span>{w.note||""}</span></div>)}{!weights.length&&<Empty icon="↗" title={t(lang,"noWeight")} text={t(lang,"noProgress")}/>}</div><section className="card"><h2>{t(lang,"goalProgress")}</h2><p className="muted">{remaining===null?t(lang,"noData"):remaining>0?`${remaining.toFixed(1)} kg ${t(lang,"remaining")}`:`${Math.abs(remaining).toFixed(1)} kg ${t(lang,"over")}`}</p></section></>}
function ReportStat({value,label}:any){return <div className="reportStat"><strong>{value}</strong><span>{label}</span></div>}
function MiniChart({values,labels}:{values:number[];labels:string[]}){if(!values.length)return <Empty icon="↗" title="No data" text=""/>;const min=Math.min(...values),max=Math.max(...values),span=Math.max(.1,max-min);return <div className="miniChart">{values.map((v,i)=><div className="chartCol" key={i}><div className="chartBar" style={{height:`${25+((v-min)/span)*70}%`}}/><small>{labels[i]}</small></div>)}</div>}

function CheckinCard({lang,checkin,onSave}:any){const [water,setWater]=useState(checkin?.water||0),[steps,setSteps]=useState(checkin?.steps||0),[sleep,setSleep]=useState(checkin?.sleep||0),[mood,setMood]=useState(checkin?.mood||3);useEffect(()=>{setWater(checkin?.water||0);setSteps(checkin?.steps||0);setSleep(checkin?.sleep||0);setMood(checkin?.mood||3)},[checkin]);return <section className="card checkinCard"><div className="checkGrid"><label>○ {t(lang,"water")}<input type="number" min="0" value={water} onChange={e=>setWater(Number(e.target.value))}/></label><label>↗ {t(lang,"steps")}<input type="number" min="0" value={steps} onChange={e=>setSteps(Number(e.target.value))}/></label><label>◷ {t(lang,"sleep")}<input type="number" min="0" step="0.5" value={sleep} onChange={e=>setSleep(Number(e.target.value))}/></label><label>◉ {t(lang,"mood")}<select value={mood} onChange={e=>setMood(Number(e.target.value))}><option value="5">😄 {t(lang,"moodGreat")}</option><option value="3">🙂 {t(lang,"moodOkay")}</option><option value="1">😕 {t(lang,"moodLow")}</option></select></label></div><button className="secondaryButton fullButton" onClick={()=>onSave({date:todayKey(),water,steps,sleep,mood})}>{t(lang,"saveCheckin")}</button></section>}

function FoodScanner({lang,onClose,onAdd}:{lang:Lang;onClose:()=>void;onAdd:(meal:Omit<Meal,"id"|"createdAt">)=>void}){const [preview,setPreview]=useState(""),[blob,setBlob]=useState<Blob|null>(null),[result,setResult]=useState<any>(null),[error,setError]=useState(""),[loading,setLoading]=useState(false);async function choose(file?:File){if(!file)return;setError("");setResult(null);try{const b=await compressImage(file);setBlob(b);setPreview(URL.createObjectURL(b))}catch(e){setError(e instanceof Error?e.message:"Image processing failed")}}async function analyze(){if(!blob)return;setLoading(true);setError("");try{const dataUrl=await blobToDataUrl(blob);const r=await fetch("/api/food",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({imageDataUrl:dataUrl})});const data=await r.json();if(!r.ok)throw new Error(data.error||"AI analysis failed.");setResult(data)}catch(e){setError(e instanceof Error?e.message:"AI analysis failed.")}finally{setLoading(false)}}return <div className="modalBackdrop"><div className="scanSheet"><div className="modalHeader"><div><span className="eyebrow">{t(lang,"ai")}</span><h2>{t(lang,"scanFood")}</h2></div><button className="close" onClick={onClose}>×</button></div>{!result&&<><div className="uploadBox">{preview?<img src={preview} alt="Food preview"/>:<div><div className="uploadIcon">⌁</div><strong>{t(lang,"scanFood")}</strong><p>{t(lang,"reviewBeforeSaving")}</p></div>}</div><div className="scanButtons"><label className="secondaryButton">{lang==="ar"?"اختار صورة":"Choose photo"}<input type="file" accept="image/*" capture="environment" hidden onChange={e=>choose(e.target.files?.[0])}/></label>{preview&&<button className="primaryButton" disabled={loading} onClick={analyze}>{loading?"…":"✦ "+(lang==="ar"?"حلّل الصورة":"Analyze photo")}</button>}</div></>}{error&&<div className="errorBox">{error}</div>}{result&&<ScanResult lang={lang} result={result} blob={blob} onAdd={onAdd} onRescan={()=>{setResult(null);setPreview("");setBlob(null)}}/>}</div></div>}
function ScanResult({lang,result,blob,onAdd,onRescan}:any){const [mealType,setMealType]=useState<any>("Lunch");const [items,setItems]=useState<any[]>(()=>result.items||[]);const totals=useMemo(()=>items.reduce((a,x)=>({calories:a.calories+Number(x.calories||0),protein:a.protein+Number(x.protein_g||0),carbs:a.carbs+Number(x.carbs_g||0),fat:a.fat+Number(x.fat_g||0)}),{calories:0,protein:0,carbs:0,fat:0}),[items]);const update=(i:number,f:string,v:number)=>setItems(p=>p.map((x,j)=>j===i?{...x,[f]:v}:x));return <div className="scanResult"><div className="resultBanner"><div><span className="muted">{items.some((x:any)=>x.nutrition_database_match)?t(lang,"dbMatch"):t(lang,"aiEstimate")}</span><h2>{result.name}</h2></div><button className="secondaryButton" onClick={onRescan}>{lang==="ar"?"صورة تانية":"Rescan"}</button></div>{items.map((item:any,i:number)=><div className="foodCard" key={i}><div className="foodCardTop"><strong>{item.name}</strong>{item.nutrition_database_match?<span className="sourceChip">✓ {item.nutrition_source}</span>:<span className="sourceChip mutedChip">{t(lang,"aiEstimate")}</span>}</div><div className="confidenceGrid"><ConfidenceBadge lang={lang} label={t(lang,"foodConfidence")} value={item.identification_confidence}/><ConfidenceBadge lang={lang} label={t(lang,"portionConfidence")} value={item.portion_confidence}/><ConfidenceBadge lang={lang} label={t(lang,"nutritionConfidence")} value={item.nutrition_database_match?item.nutrition_match_confidence:item.nutrition_confidence}/></div><div className="referenceLine">{item.nutrition_reference_name?`✓ ${item.nutrition_reference_name} · ${t(lang,"per100g")}`:t(lang,"aiEstimate")}</div><div className="editGrid"><label>{t(lang,"grams")}<input type="number" min="1" value={item.estimated_grams??100} onChange={e=>update(i,"estimated_grams",Number(e.target.value))}/></label><label>{t(lang,"calories")}<input type="number" value={item.calories??0} onChange={e=>update(i,"calories",Number(e.target.value))}/></label><label>{t(lang,"protein")}<input type="number" step="0.1" value={item.protein_g??0} onChange={e=>update(i,"protein_g",Number(e.target.value))}/></label><label>{t(lang,"carbs")}<input type="number" step="0.1" value={item.carbs_g??0} onChange={e=>update(i,"carbs_g",Number(e.target.value))}/></label><label>{t(lang,"fat")}<input type="number" step="0.1" value={item.fat_g??0} onChange={e=>update(i,"fat_g",Number(e.target.value))}/></label></div>{item.nutrition_note&&<div className="note">{item.nutrition_note}</div>}</div>)}<div className="resultTotal"><span>{t(lang,"total")}</span><strong>{Math.round(totals.calories)} {t(lang,"kcal")}</strong></div><div className="macroGrid"><Macro lang={lang} value={totals.protein} goal={0} label="protein"/><Macro lang={lang} value={totals.carbs} goal={0} label="carbs"/><Macro lang={lang} value={totals.fat} goal={0} label="fat"/></div><div className="note">{items.some((x:any)=>x.nutrition_database_match)?t(lang,"dbCalculated"):t(lang,"noStrongMatch")}</div><label className="fullLabel">{t(lang,"mealType")}<select value={mealType} onChange={e=>setMealType(e.target.value)}>{mealTypes.map(x=><option key={x}>{x}</option>)}</select></label><button className="primaryButton fullButton" onClick={()=>onAdd({name:result.name,calories:Math.round(totals.calories),protein:Number(totals.protein.toFixed(1)),carbs:Number(totals.carbs.toFixed(1)),fat:Number(totals.fat.toFixed(1)),image:blob||undefined,mealType})}>✓ {t(lang,"addToday")}</button></div>}
function ConfidenceBadge({label,value,lang}:{label:string;value:number;lang:Lang}){const pct=Math.round(Math.max(0,Math.min(1,Number(value)||0))*100);const level=pct>=80?"high":pct>=60?"medium":"low";return <div className={`confidenceBadge ${level}`}><span>{label}</span><strong>{pct}%</strong><small>{t(lang,level as any)}</small></div>}

function FoodLookup({lang,onClose,onAdd}:{lang:Lang;onClose:()=>void;onAdd:(meal:Omit<Meal,"id"|"createdAt">)=>void}){const [query,setQuery]=useState(""),[barcode,setBarcode]=useState(""),[items,setItems]=useState<any[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(""),[camera,setCamera]=useState(false),[favorites,setFavorites]=useState<FoodFavorite[]>([]),[grams,setGrams]=useState<Record<string,number>>({}),[mealType,setMealType]=useState<any>("Lunch");const videoRef=useRef<HTMLVideoElement>(null);useEffect(()=>{db.favorites.orderBy("createdAt").reverse().limit(12).toArray().then(setFavorites)},[]);useEffect(()=>{if(!camera||!videoRef.current)return;let stream:MediaStream|undefined,timer:any,stopped=false;(async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});const video=videoRef.current!;video.srcObject=stream;await video.play();const Detector=(window as any).BarcodeDetector;if(!Detector){setError(t(lang,"cameraUnavailable"));return}const detector=new Detector({formats:["ean_13","ean_8","upc_a","upc_e"]});const scan=async()=>{if(stopped)return;try{const codes=await detector.detect(video);if(codes?.[0]?.rawValue){const code=codes[0].rawValue;setBarcode(code);setCamera(false);await search("",code);return}}catch{}timer=setTimeout(scan,450)};scan()}catch{setError(t(lang,"cameraBlocked"))}})();return()=>{stopped=true;if(timer)clearTimeout(timer);stream?.getTracks().forEach(x=>x.stop())}},[camera,lang]);async function search(q:string,code=""){if(!q&&!code)return;setLoading(true);setError("");try{const url=code?`/api/food/search?barcode=${encodeURIComponent(code)}`:`/api/food/search?q=${encodeURIComponent(q)}`;const r=await fetch(url);const data=await r.json();if(!r.ok)throw new Error(data.error||"Food search failed");setItems(data.items||[]);if(!(data.items||[]).length)setError(t(lang,"noResults"))}catch(e){setError(e instanceof Error?e.message:"Food search failed.")}finally{setLoading(false)}}const key=(x:any)=>`${x.source}:${x.referenceId||x.name}`;const isFav=(x:any)=>favorites.some(f=>(x.barcode&&f.barcode===x.barcode)||`${f.source}:${f.referenceId}`===key(x));async function toggleFavorite(x:any){const old=favorites.find(f=>(x.barcode&&f.barcode===x.barcode)||`${f.source}:${f.referenceId}`===key(x));if(old?.id){await db.favorites.delete(old.id);setFavorites(favorites.filter(f=>f.id!==old.id));return}const createdAt=Date.now();const id=await db.favorites.add({name:x.name,brand:x.brand,barcode:x.barcode,source:x.source,referenceId:x.referenceId,calories100g:x.calories100g,protein100g:x.protein100g,carbs100g:x.carbs100g,fat100g:x.fat100g,fiber100g:x.fiber100g,createdAt});setFavorites([{...x,id,createdAt},...favorites])}function add(x:any){const g=Math.max(1,Number(grams[key(x)]||100)),f=g/100;onAdd({name:x.name,calories:Math.round(x.calories100g*f),protein:Number((x.protein100g*f).toFixed(1)),carbs:Number((x.carbs100g*f).toFixed(1)),fat:Number((x.fat100g*f).toFixed(1)),mealType})}return <Modal title={t(lang,"findFood")} onClose={onClose} wide><div className="lookupTopBar"><button className="primaryButton" onClick={()=>setCamera(true)}>▣ {t(lang,"scanBarcode")}</button><span>{t(lang,"searchFood")}</span></div>{camera&&<div className="barcodeCamera"><video ref={videoRef} playsInline muted/><button className="cameraClose" onClick={()=>setCamera(false)}>{t(lang,"close")}</button></div>}<div className="searchRow"><input inputMode="numeric" placeholder={t(lang,"barcodePlaceholder")} value={barcode} onChange={e=>setBarcode(e.target.value)}/><button onClick={()=>search("",barcode)}>{t(lang,"barcode")}</button></div><div className="searchRow"><input placeholder={t(lang,"searchPlaceholder")} value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&search(query)}/><button onClick={()=>search(query)} disabled={loading}>{loading?"…":t(lang,"searchFood")}</button></div>{error&&<div className="errorBox">{error}</div>}{favorites.length>0&&<><SectionTitle lang={lang} title={t(lang,"favorites")} meta={t(lang,"savedLocally")}/><div className="favoriteChips">{favorites.slice(0,8).map(f=><button key={f.id} onClick={()=>setItems([f])}>★ {f.name}</button>)}</div></>}<div className="lookupResults">{items.map(x=><div className="lookupCard" key={key(x)}><div className="lookupName"><div><strong>{x.name}</strong>{x.brand&&<small>{x.brand}</small>}<small>{x.source} · {x.note||t(lang,"per100g")}</small></div><button className={`starButton ${isFav(x)?"saved":""}`} onClick={()=>toggleFavorite(x)}>{isFav(x)?"★":"☆"}</button></div><div className="lookupMacros"><b>{Math.round(x.calories100g)} {t(lang,"kcal")}</b><span>P {Number(x.protein100g).toFixed(1)}g</span><span>C {Number(x.carbs100g).toFixed(1)}g</span><span>F {Number(x.fat100g).toFixed(1)}g</span></div><div className="lookupAdd"><input type="number" min="1" value={grams[key(x)]||100} onChange={e=>setGrams({...grams,[key(x)]:Number(e.target.value)})}/><span>{t(lang,"grams")}</span><select value={mealType} onChange={e=>setMealType(e.target.value)}>{mealTypes.map(x=><option key={x}>{x}</option>)}</select><button onClick={()=>add(x)}>{t(lang,"add")}</button></div></div>)}</div>{!items.length&&!error&&<Empty icon="⌕" title={t(lang,"searchFood")} text={t(lang,"searchHint")}/>}</Modal>}

function WorkoutEditor({lang,onClose,onSave}:any){const [name,setName]=useState(""),[date,setDate]=useState(todayKey()),[duration,setDuration]=useState(60),[calories,setCalories]=useState(300),[notes,setNotes]=useState(""),[exercises,setExercises]=useState<any[]>([]);const addExercise=()=>setExercises([...exercises,{name:"",sets:3,reps:10,weight:0,completed:false}]);return <Modal title={t(lang,"createWorkout")} onClose={onClose}><div className="formGrid"><label>{t(lang,"workout")}<input value={name} onChange={e=>setName(e.target.value)} placeholder="Push day"/></label><label>{t(lang,"duration")}<input type="number" value={duration} onChange={e=>setDuration(Number(e.target.value))}/></label><label>Date<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>kcal<input type="number" value={calories} onChange={e=>setCalories(Number(e.target.value))}/></label></div><label className="fullLabel">{t(lang,"notes")}<textarea value={notes} onChange={e=>setNotes(e.target.value)}/></label><SectionTitle lang={lang} title={t(lang,"exercise")} meta={`${exercises.length}`}/>{exercises.map((e,i)=><div className="exerciseEdit" key={i}><input placeholder={t(lang,"exercise")} value={e.name} onChange={x=>{const n=[...exercises];n[i].name=x.target.value;setExercises(n)}}/><input type="number" value={e.sets} onChange={x=>{const n=[...exercises];n[i].sets=Number(x.target.value);setExercises(n)}}/><input type="number" value={e.reps} onChange={x=>{const n=[...exercises];n[i].reps=Number(x.target.value);setExercises(n)}}/><input type="number" value={e.weight} onChange={x=>{const n=[...exercises];n[i].weight=Number(x.target.value);setExercises(n)}}/><button className="iconButton" onClick={()=>setExercises(exercises.filter((_,j)=>j!==i))}>×</button></div>)}<button className="secondaryButton fullButton" onClick={addExercise}>＋ {t(lang,"addExercise")}</button><button className="primaryButton fullButton" onClick={()=>onSave({name:name||(lang==="ar"?"تمرين جديد":"New workout"),date,duration,calories,notes,exercises,completed:false})}>{t(lang,"save")}</button></Modal>}
function WeightEditor({lang,onClose,onSave}:any){const [weight,setWeight]=useState(""),[note,setNote]=useState("");return <Modal title={t(lang,"addWeight")} onClose={onClose}><div className="bigInput"><input autoFocus type="number" step="0.1" placeholder="75" value={weight} onChange={e=>setWeight(e.target.value)}/><span>kg</span></div><label className="fullLabel">{t(lang,"notes")}<textarea value={note} onChange={e=>setNote(e.target.value)}/></label><button className="primaryButton fullButton" disabled={!weight} onClick={()=>onSave(Number(weight),note)}>{t(lang,"save")}</button></Modal>}
function GoalEditor({lang,goal,onClose,onSave}:any){const [g,setG]=useState(goal);return <Modal title={t(lang,"goals")} onClose={onClose}><div className="formGrid"><label>{t(lang,"calories")}<input type="number" value={g.calories} onChange={e=>setG({...g,calories:Number(e.target.value)})}/></label><label>{t(lang,"protein")}<input type="number" value={g.protein} onChange={e=>setG({...g,protein:Number(e.target.value)})}/></label><label>{t(lang,"carbs")}<input type="number" value={g.carbs} onChange={e=>setG({...g,carbs:Number(e.target.value)})}/></label><label>{t(lang,"fat")}<input type="number" value={g.fat} onChange={e=>setG({...g,fat:Number(e.target.value)})}/></label><label>{t(lang,"targetWeight")}<input type="number" step="0.1" value={g.targetWeight} onChange={e=>setG({...g,targetWeight:Number(e.target.value)})}/></label></div><button className="primaryButton fullButton" onClick={()=>onSave(g)}>{t(lang,"save")}</button></Modal>}
function ProfileEditor({lang,profile,onClose,onSave}:any){const [p,setP]=useState<Profile>(profile||{name:"",age:20,sex:"male",heightCm:175,currentWeight:75,activity:"moderate",goalMode:"maintain",targetWeight:75,updatedAt:Date.now()});const calc=calculateTargets(p);return <Modal title={t(lang,"profile")} onClose={onClose}><div className="formGrid"><label>{t(lang,"age")}<input type="number" min="13" max="100" value={p.age} onChange={e=>setP({...p,age:Number(e.target.value)})}/></label><label>{t(lang,"sex")}<select value={p.sex} onChange={e=>setP({...p,sex:e.target.value as Sex})}><option value="male">{t(lang,"male")}</option><option value="female">{t(lang,"female")}</option></select></label><label>{t(lang,"height")}<input type="number" value={p.heightCm} onChange={e=>setP({...p,heightCm:Number(e.target.value)})}/></label><label>{t(lang,"weight")}<input type="number" step="0.1" value={p.currentWeight} onChange={e=>setP({...p,currentWeight:Number(e.target.value)})}/></label><label>{t(lang,"activity")}<select value={p.activity} onChange={e=>setP({...p,activity:e.target.value as ActivityLevel})}><option value="sedentary">{t(lang,"activitySedentary")}</option><option value="light">{t(lang,"activityLight")}</option><option value="moderate">{t(lang,"activityModerate")}</option><option value="high">{t(lang,"activityHigh")}</option><option value="athlete">{t(lang,"activityAthlete")}</option></select></label><label>{t(lang,"goalMode")}<select value={p.goalMode} onChange={e=>setP({...p,goalMode:e.target.value as GoalMode})}><option value="cut">{t(lang,"cut")}</option><option value="maintain">{t(lang,"maintain")}</option><option value="bulk">{t(lang,"bulk")}</option></select></label><label>{t(lang,"targetWeight")}<input type="number" step="0.1" value={p.targetWeight} onChange={e=>setP({...p,targetWeight:Number(e.target.value)})}/></label></div><div className="targetPreview"><span>{t(lang,"targetSummary")}</span><strong>{calc.calories} kcal · {calc.protein}g P · {calc.carbs}g C · {calc.fat}g F</strong><small>{t(lang,"maintenance")}: {calc.maintenance} · BMR: {calc.bmr}</small></div><button className="primaryButton fullButton" onClick={()=>onSave(p)}>{t(lang,"saveProfile")}</button></Modal>}
function ProgramEditor({lang,onClose,onSave}:any){const [name,setName]=useState(""),[days,setDays]=useState<any[]>([{name:lang==="ar"?"اليوم 1":"Day 1",exercises:[{name:"",sets:3,reps:10,weight:0,completed:false}]}]);const addDay=()=>setDays([...days,{name:`${lang==="ar"?"اليوم":"Day"} ${days.length+1}`,exercises:[]}]);return <Modal title={t(lang,"createProgram")} onClose={onClose}><label>{t(lang,"newProgram")}<input value={name} onChange={e=>setName(e.target.value)} placeholder="Push / Pull / Legs"/></label>{days.map((d,i)=><div className="programEditor" key={i}><div className="sectionTitle"><input value={d.name} onChange={e=>{const n=[...days];n[i].name=e.target.value;setDays(n)}}/><span>{d.exercises.length}</span></div>{d.exercises.map((e:any,j:number)=><div className="exerciseEdit" key={j}><input placeholder={t(lang,"exercise")} value={e.name} onChange={x=>{const n=[...days];n[i].exercises[j].name=x.target.value;setDays(n)}}/><input type="number" value={e.sets} onChange={x=>{const n=[...days];n[i].exercises[j].sets=Number(x.target.value);setDays(n)}}/><input type="number" value={e.reps} onChange={x=>{const n=[...days];n[i].exercises[j].reps=Number(x.target.value);setDays(n)}}/><input type="number" value={e.weight} onChange={x=>{const n=[...days];n[i].exercises[j].weight=Number(x.target.value);setDays(n)}}/><button className="iconButton" onClick={()=>{const n=[...days];n[i].exercises=n[i].exercises.filter((_:any,k:number)=>k!==j);setDays(n)}}>×</button></div>)}<button className="secondaryButton" onClick={()=>{const n=[...days];n[i].exercises.push({name:"",sets:3,reps:10,weight:0,completed:false});setDays(n)}}>＋ {t(lang,"addExercise")}</button></div>)}<button className="secondaryButton fullButton" onClick={addDay}>＋ {t(lang,"addDay")}</button><button className="primaryButton fullButton" onClick={()=>onSave({name:name||t(lang,"newProgram"),days,updatedAt:Date.now()})}>{t(lang,"save")}</button></Modal>}
function progressionTips(lang:Lang, workouts:Workout[]){const map=new Map<string,{weight:number;reps:number;date:string}>();for(const w of workouts.filter(x=>x.completed)){for(const e of w.exercises){if(!e.name)continue;const key=e.name.trim().toLowerCase();const prev=map.get(key);if(!prev||e.weight>prev.weight||(e.weight===prev.weight&&e.reps>prev.reps))map.set(key,{weight:e.weight,reps:e.reps,date:w.date})}}const top=[...map.entries()].sort((a,b)=>b[1].weight-a[1].weight).slice(0,3);if(!top.length)return [t(lang,"progressionEmpty")];return top.map(([name,v])=>`${name}: ${t(lang,"bestSet")} ${v.weight}kg × ${v.reps}. ${t(lang,"progressionNext")}`)}

function defaultPrograms():WorkoutProgram[]{const now=Date.now();return [{name:"Push",updatedAt:now,days:[{name:"Push A",exercises:[{name:"Bench Press",sets:3,reps:8,weight:0,completed:false},{name:"Shoulder Press",sets:3,reps:10,weight:0,completed:false},{name:"Triceps Pushdown",sets:3,reps:12,weight:0,completed:false}]}]},{name:"Pull",updatedAt:now,days:[{name:"Pull A",exercises:[{name:"Lat Pulldown",sets:3,reps:10,weight:0,completed:false},{name:"Row",sets:3,reps:10,weight:0,completed:false},{name:"Biceps Curl",sets:3,reps:12,weight:0,completed:false}]}]},{name:"Legs",updatedAt:now,days:[{name:"Legs A",exercises:[{name:"Squat",sets:3,reps:8,weight:0,completed:false},{name:"Romanian Deadlift",sets:3,reps:10,weight:0,completed:false},{name:"Leg Press",sets:3,reps:12,weight:0,completed:false}]}]}]}

function Settings({lang,onLang,onClose,onClear,onExport,onImport,onCsv,onHuaweiImport,huaweiSync}:any){const fileRef=useRef<HTMLInputElement>(null),huaweiRef=useRef<HTMLInputElement>(null);return <Modal title={t(lang,"settings")} onClose={onClose}><div className="languageSwitch"><span>{t(lang,"language")}</span><div><button className={lang==="en"?"selected":""} onClick={()=>onLang("en")}>{t(lang,"english")}</button><button className={lang==="ar"?"selected":""} onClick={()=>onLang("ar")}>{t(lang,"egyptian")}</button></div></div><section className="card syncCard"><div className="syncHead"><div><span className="eyebrow">Huawei Health</span><h3>{huaweiSync?t(lang,"huaweiConnected"):t(lang,"huaweiReady")}</h3><small>{huaweiSync?`${t(lang,"lastSync")}: ${new Date(huaweiSync.syncedAt).toLocaleString()}`:t(lang,"huaweiHint")}</small></div><span className={`syncDot ${huaweiSync?"on":""}`}>●</span></div><div className="settingsActions"><button className="primaryButton" onClick={()=>huaweiRef.current?.click()}>↻ {t(lang,"syncHuawei")}</button><input ref={huaweiRef} type="file" accept=".json,.csv,text/csv,application/json" hidden onChange={e=>e.target.files?.[0]&&onHuaweiImport(e.target.files[0])}/></div><p className="note">{t(lang,"huaweiBridgeNote")}</p></section><div className="settingsList"><div className="settingRow"><div><strong>{t(lang,"offline")}</strong><small>{t(lang,"offlineHint")}</small></div><span>✓</span></div><div className="settingRow"><div><strong>{t(lang,"privacy")}</strong><small>{t(lang,"privacyHint")}</small></div><span>🔒</span></div></div><div className="settingsActions"><button className="secondaryButton" onClick={onExport}>↗ {t(lang,"exportData")}</button><button className="secondaryButton" onClick={()=>fileRef.current?.click()}>↙ {t(lang,"importData")}</button><input ref={fileRef} type="file" accept="application/json" hidden onChange={e=>e.target.files?.[0]&&onImport(e.target.files[0])}/><button className="secondaryButton" onClick={onCsv}>▤ {t(lang,"exportCsv")}</button></div><button className="dangerButton" onClick={onClear}>{t(lang,"deleteData")}</button></Modal>}
function parseHuaweiCsv(text:string){const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(lines.length<2)return [];const headers=lines[0].split(",").map(x=>x.trim().replace(/^"|"$/g,""));return lines.slice(1).map(line=>{const cols=line.split(",");const o:any={};headers.forEach((h,i)=>o[h]=String(cols[i]||"").trim().replace(/^"|"$/g,""));return o})}
function Modal({title,onClose,children,wide}:any){return <div className="modalBackdrop"><div className={`modal ${wide?"wide":""}`}><div className="modalHeader"><h2>{title}</h2><button className="close" onClick={onClose}>×</button></div>{children}</div></div>}
function downloadFile(name:string,text:string,type:string){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function compressImage(file:File):Promise<Blob>{const bitmap=await createImageBitmap(file);const max=1280,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Could not process image.");ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error("Image conversion failed.")),"image/jpeg",.82))}
async function blobToDataUrl(blob:Blob):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onloadend=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(blob)})}
